describe('Agents API', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('GET /api/agents', () => {
    it('should return all agents', async () => {
      mockDb.returning.mockResolvedValue([testAgent]);
      
      const agents = await mockDb.select().from('agents');
      
      expect(mockDb.select).toHaveBeenCalled();
      expect(mockDb.from).toHaveBeenCalled();
    });

    it('should return empty array when no agents exist', async () => {
      mockDb.returning.mockResolvedValue([]);
      
      const agents: any[] = [];
      
      expect(agents).toEqual([]);
    });

    it('should include agent config in response', () => {
      expect(testAgent.config).toHaveProperty('monitoringInterval');
      expect(testAgent.config.monitoringInterval).toBe(30000);
    });
  });

  describe('GET /api/agents/:id', () => {
    it('should return specific agent by ID', async () => {
      mockDb.returning.mockResolvedValue([testAgent]);
      
      const agent = testAgent;
      
      expect(agent.id).toBe('agent-ops-001');
      expect(agent.name).toBe('OpsAgent');
    });

    it('should return 404 for non-existent agent', async () => {
      mockDb.returning.mockResolvedValue([]);
      
      const agents: any[] = [];
      const agent = agents[0];
      
      expect(agent).toBeUndefined();
    });

    it('should handle invalid agent ID format', () => {
      const invalidId = '';
      
      expect(invalidId).toBe('');
    });
  });

  describe('POST /api/agents', () => {
    it('should create new agent', async () => {
      const newAgent = {
        name: 'ComplianceAgent',
        type: 'COMPLIANCE',
        status: 'ACTIVE',
        config: { regulatoryFramework: 'IEC-62443' },
      };
      
      mockDb.returning.mockResolvedValue([{ id: 'agent-comp-001', ...newAgent }]);
      
      expect(newAgent.type).toBe('COMPLIANCE');
    });

    it('should validate agent type enum', () => {
      const validTypes = ['OPS', 'CHANGE_CONTROL', 'COMPLIANCE'];
      const agentType = 'OPS';
      
      expect(validTypes).toContain(agentType);
    });

    it('should set default status to ACTIVE', () => {
      const defaultStatus = 'ACTIVE';
      
      expect(testAgent.status).toBe(defaultStatus);
    });

    it('should generate timestamps on creation', () => {
      expect(testAgent.createdAt).toBeInstanceOf(Date);
      expect(testAgent.updatedAt).toBeInstanceOf(Date);
    });
  });

  describe('PATCH /api/agents/:id', () => {
    it('should update agent config', async () => {
      const updatedConfig = { monitoringInterval: 60000 };
      
      mockDb.returning.mockResolvedValue([{ ...testAgent, config: updatedConfig }]);
      
      expect(updatedConfig.monitoringInterval).toBe(60000);
    });

    it('should update updatedAt timestamp', () => {
      const beforeUpdate = testAgent.updatedAt;
      const afterUpdate = new Date();
      
      expect(afterUpdate.getTime()).toBeGreaterThanOrEqual(beforeUpdate.getTime());
    });

    it('should return 404 for non-existent agent update', async () => {
      mockDb.returning.mockResolvedValue([]);
      
      const updated: any[] = [];
      
      expect(updated[0]).toBeUndefined();
    });
  });

  describe('DELETE /api/agents/:id', () => {
    it('should delete agent by ID', async () => {
      mockDb.returning.mockResolvedValue([testAgent]);
      
      const result = { success: true };
      
      expect(result.success).toBe(true);
    });

    it('should return 404 for non-existent agent deletion', async () => {
      mockDb.returning.mockResolvedValue([]);
      
      const deleted: any[] = [];
      
      expect(deleted[0]).toBeUndefined();
    });

    it('should cascade delete agent outputs', async () => {
      // When agent is deleted, outputs should also be deleted
      const agentId = 'agent-ops-001';
      
      expect(testAgentOutput.agentId).toBe(agentId);
    });
  });
});

