describe('Agent Proposals API', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('GET /api/agents/proposals', () => {
    it('should return all proposals', async () => {
      mockDb.returning.mockResolvedValue([testProposal]);
      
      expect(testProposal.proposalType).toBe('CODE_CHANGE');
    });

    it('should filter by status', () => {
      const pendingProposals = [testProposal].filter(p => p.status === 'PENDING');
      
      expect(pendingProposals).toHaveLength(1);
    });
  });

  describe('POST /api/agents/proposals', () => {
    it('should create new proposal', async () => {
      const newProposal = {
        agentId: 'agent-change-001',
        proposalType: 'CONFIG_CHANGE',
        title: 'Update monitoring threshold',
        description: 'Reduce false positive alerts',
        requiredApprovals: 1,
      };
      
      expect(newProposal.requiredApprovals).toBeGreaterThan(0);
    });

    it('should require at least one approval', () => {
      expect(testProposal.requiredApprovals).toBeGreaterThan(0);
    });

    it('should set initial status to PENDING', () => {
      expect(testProposal.status).toBe('PENDING');
    });
  });

  describe('POST /api/agents/proposals/:id/approve', () => {
    it('should record approval', async () => {
      const approval = {
        approver: '0x1234567890abcdef1234567890abcdef12345678',
        comment: 'Looks good',
        approvedAt: new Date(),
      };
      
      const updatedProposal = {
        ...testProposal,
        approvals: [...testProposal.approvals, approval],
      };
      
      expect(updatedProposal.approvals).toHaveLength(1);
    });

    it('should auto-approve when threshold reached', () => {
      const proposal = {
        ...testProposal,
        requiredApprovals: 2,
        approvals: [{ approver: '0xa' }, { approver: '0xb' }],
      };
      
      const isApproved = proposal.approvals.length >= proposal.requiredApprovals;
      
      expect(isApproved).toBe(true);
    });

    it('should prevent duplicate approvals from same address', () => {
      const existingApprovers = ['0x1234'];
      const newApprover = '0x1234';
      
      const isDuplicate = existingApprovers.includes(newApprover);
      
      expect(isDuplicate).toBe(true);
    });
  });

  describe('POST /api/agents/proposals/:id/reject', () => {
    it('should update status to REJECTED', () => {
      const rejectedProposal = { ...testProposal, status: 'REJECTED' };
      
      expect(rejectedProposal.status).toBe('REJECTED');
    });

    it('should require rejection reason', () => {
      const rejection = {
        reason: 'Does not meet security requirements',
        rejectedBy: '0xsecurity-admin',
        rejectedAt: new Date(),
      };
      
      expect(rejection.reason).toBeDefined();
    });
  });

  describe('POST /api/agents/proposals/:id/execute', () => {
    it('should only execute approved proposals', () => {
      const approvedProposal = { ...testProposal, status: 'APPROVED' };
      
      expect(approvedProposal.status).toBe('APPROVED');
    });

    it('should update status to EXECUTED', () => {
      const executedProposal = { ...testProposal, status: 'EXECUTED' };
      
      expect(executedProposal.status).toBe('EXECUTED');
    });

    it('should record execution timestamp', () => {
      const executedAt = new Date();
      
      expect(executedAt).toBeInstanceOf(Date);
    });
  });
});

