describe('Governance Agents', () => {
  describe('OpsAgent', () => {
    it('should monitor system health', () => {
      const healthCheck = {
        cpuUsage: 45.2,
        memoryUsage: 62.1,
        diskUsage: 38.5,
        networkLatency: 15,
      };
      
      expect(healthCheck.cpuUsage).toBeLessThan(80); // Healthy threshold
    });

    it('should generate alerts for threshold violations', () => {
      const cpuUsage = 95; // Above threshold
      const threshold = 80;
      
      expect(cpuUsage).toBeGreaterThan(threshold);
    });

    it('should track agent uptime', () => {
      const startTime = new Date('2026-01-01');
      const now = new Date('2026-01-15');
      const uptimeMs = now.getTime() - startTime.getTime();
      const uptimeDays = uptimeMs / (1000 * 60 * 60 * 24);
      
      expect(uptimeDays).toBe(14);
    });
  });

  describe('ChangeControlAgent', () => {
    it('should validate change package structure', () => {
      const changePackage = {
        blueprintHash: '0x' + 'a'.repeat(64),
        codeHash: '0x' + 'b'.repeat(64),
        diff: '+new code\n-old code',
        testPlan: 'Run all unit tests',
        rollbackPlan: 'Revert to previous version',
      };
      
      expect(changePackage).toHaveProperty('blueprintHash');
      expect(changePackage).toHaveProperty('rollbackPlan');
    });

    it('should enforce approval workflow', () => {
      const workflow = {
        requiredApprovers: ['safety-engineer', 'ops-lead'],
        currentApprovals: ['safety-engineer'],
      };
      
      const isComplete = workflow.currentApprovals.length >= workflow.requiredApprovers.length;
      
      expect(isComplete).toBe(false);
    });

    it('should anchor approved changes to blockchain', () => {
      const changeIntent = {
        siteId: 'site-001',
        blueprintHash: '0x' + 'a'.repeat(64),
        codeHash: '0x' + 'b'.repeat(64),
        status: 'APPROVED',
      };
      
      expect(changeIntent.status).toBe('APPROVED');
    });
  });

  describe('ComplianceAgent', () => {
    it('should validate against regulatory framework', () => {
      const frameworks = ['IEC-62443', 'NIST-800-82', 'ISA-99'];
      const activeFramework = 'IEC-62443';
      
      expect(frameworks).toContain(activeFramework);
    });

    it('should generate compliance reports', () => {
      const report = {
        framework: 'IEC-62443',
        assessmentDate: new Date(),
        findings: [
          { category: 'ACCESS_CONTROL', status: 'COMPLIANT' },
          { category: 'AUDIT_LOGGING', status: 'COMPLIANT' },
        ],
        overallStatus: 'COMPLIANT',
      };
      
      expect(report.overallStatus).toBe('COMPLIANT');
    });

    it('should flag non-compliant changes', () => {
      const change = {
        type: 'DISABLE_AUDIT_LOG',
        complianceStatus: 'NON_COMPLIANT',
        reason: 'Violates IEC-62443 requirement 4.3',
      };
      
      expect(change.complianceStatus).toBe('NON_COMPLIANT');
    });
  });
});

